        category: 'سینمای جهان',
        image: 'Images/news-world-cinema-087.jpg',
        summary: 'فیلم اتریشی-آلمانی «همیشه» به کارگردانی ساندرا ولنر، جایزه قلب سارایوو برای بهترین فیلم داستانی سی‌ودومین جشنواره فیلم سارایوو را از آن خود کرد.',
        content:
            'سی‌ودومین جشنواره فیلم سارایوو در بوسنی و هرزگوین با نمایش ۲۶۹ فیلم از سراسر جهان به کار خود پایان داد و جایزه قلب سارایوو برای بهترین فیلم داستانی را به «همیشه» (Everytime) ساخته ساندرا ولنر، کارگردان اتریشی، اهدا کرد؛ اثری که هیئت داوران آن را روایتی سینمایی و رؤیاگونه از سوگ توصیف کردند. آنا اوروشادزه برای فیلم «نقش مکمل» جایزه بهترین کارگردانی و اوا کوستیچ برای فیلم «۱۷» جایزه بهترین بازیگری زن را دریافت کردند.\n\n' +
            'جایزه قلب سارایوو برای بهترین مستند نیز به «نگه‌داشتن یک کوه» ساخته بیلیانا توتوروف و پتار گلومازیچ رسید که با این برد، واجد شرایط رقابت بخش بهترین فیلم بین‌المللی اسکار ۲۰۲۷ نیز شد.',
