        content:
            'چهل‌ودومین دوره جشنواره بین‌المللی فیلم کوتاه تهران، یکی از قدیمی‌ترین و معتبرترین رویدادهای سینمای کوتاه ایران که از سوی انجمن سینمای جوانان ایران برگزار می‌شود، با آیین اختتامیه‌ای در استادیوم تنیس مجموعه ایران‌مال به کار خود پایان داد. در بخش مسابقه سینمای ایران، جایزه بهترین فیلم به تهیه‌کننده فیلم «خداحافظ آشغال» به کارگردانی بهرام... و تهیه‌کنندگی مهدی بدرلو رسید؛ فیلمی که پیش از این نیز در میان نامزدهای نهایی این بخش قرار داشت.\\n\\n' +
            'در میان دیگر نامزدهای بخش بهترین فیلم سینمای ایران می‌توان به آثاری چون «تیتان» به کارگردانی هادی رضایتی چَران و میلاد هرندی، «انار» ساخته ملیحه جلالی، «و زندگی برای همه» ساخته محسن اصدق‌پور و «ذره» ساخته بهنود بدیعی و فردین انصاری اشاره کرد. رقابت فشرده میان این آثار، بار دیگر نشان داد که جشنواره فیلم کوتاه تهران همچنان مهم‌ترین ویترین معرفی استعدادهای تازه سینمای کوتاه ایران به شمار می‌رود.',
        date: '1404-08-03',
        sourceLabel: 'فرارو',
        sourceUrl: 'https://fararu.com/fa/news/917135',
