        category: 'فیلم کوتاه',
        image: 'Images/news-short-film-103.jpg',
        summary: 'در بخش‌های جانبی چهل‌ودومین جشنواره فیلم کوتاه تهران، جوایز بهترین پویانمایی، بهترین فیلم تجربی و بهترین اقتباس نیز به آثار برگزیده اهدا شد.',
        content:
            'در کنار جایزه اصلی بهترین فیلم بخش سینمای ایران، چهل‌ودومین جشنواره فیلم کوتاه تهران جوایز متعددی را نیز در بخش‌های تخصصی خود اهدا کرد. جایزه بهترین فیلم پویانمایی به میرعلی حسینی‌اصلی برای فیلم «بی‌او و ۲۰۰۲» رسید و در بخش فیلم تجربی، جایزه بهترین فیلم به عباس شکوری برای «یادداشت‌های زیرزمینی» و جایزه بهترین کارگردانی این بخش به محمد مستوفی برای فیلم «یاشام» تعلق گرفت.\\n\\n' +
            'در بخش فیلم‌های کوتاه اقتباسی نیز، فیلم «آغ باش» ساخته صمد قربان‌زاده به‌عنوان بهترین اثر این بخش شناخته شد. تنوع جوایز اهدایی در بخش‌های پویانمایی، تجربی و اقتباس، نشان‌دهنده گستردگی ژانرها و سبک‌های حاضر در یکی از پرشمارترین دوره‌های اخیر جشنواره فیلم کوتاه تهران بود.',
