            metaDescription: 'فیلم کوتاه «ماندالا» پس از کسب جایزه بهترین فیلم کوتاه تجربی از جشنواره TINFF کانادا، به جشنواره بین‌المللی MISAFF کانادا راه یافت. گزارش کامل این خبر را در مستر شورت‌فیلم بخوانید.',
            keywords: 'ماندالا, بهنام خسروی, TINFF, MISAFF, جشنواره فیلم کانادا, مستر شورت‌فیلم, فیلم کوتاه ایرانی, جشنواره‌ها'
