        content: "«اسکلت دوست‌داشتنیِ من» ساخته رضا پُردل از تهران، یکی از ۶۳ فیلم کوتاه داستانی است که به بخش ملی چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران راه پیدا کرده‌اند. اسامی این آثار از سوی ستاد اطلاع‌رسانی جشنواره اعلام شده است.\n\nهیئت انتخاب این بخش هفت نفر بوده‌اند: اسما ابراهیم‌زادگان، الهام اسدی، محسن اصدق‌پور، رضا فهیمی، وحید موسائیان، الهام معروفی و وحید نامی.\n\nجشنواره ۲۵ تا ۳۰ مهر، به دبیری بهروز شعیبی و در پردیس سینمایی ملت برگزار خواهد شد.",
