        content: "در فهرست ۶۳ فیلم داستانی بخش ملی چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران، اسم «گربه در برف» به کارگردانی محمدسینا حیدری‌زاده از تهران هم دیده می‌شود.\n\nاین فهرست به انتخاب اسما ابراهیم‌زادگان، الهام اسدی، محسن اصدق‌پور، رضا فهیمی، وحید موسائیان، الهام معروفی و وحید نامی تعیین شده و از طریق ستاد اطلاع‌رسانی جشنواره منتشر شده است.\n\nرویداد امسال از ۲۵ تا ۳۰ مهر در پردیس سینمایی ملت برپا می‌شود و دبیری آن با بهروز شعیبی است.",
