        content: "اسامی آثار راه‌یافته به بخش بین‌الملل چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران اعلام شد و «ماهی‌ها گریه نمی‌کنند» به کارگردانی فرشاد فرهنگ از ایران هم در آن حضور دارد؛ این فیلم در بخش هوش مصنوعی قرار گرفته است.\n\nآثار بخش بین‌الملل در پنج دسته یعنی هوش مصنوعی، پویانمایی، مستند، تجربی و داستانی معرفی شده‌اند. انتخاب آن‌ها با مصطفی احمدی، مجتبا اسماعیل‌زاده، سیدمحسن پورمحسنی شکیب، حمید حسینی، حسن حکمت‌روش، هادی رضایتی، دینا رضایی، روناک رنجی، مهری رحیم‌زاده، زهره زمانی، سیامک سلیمانی، فرید طهماسبی، نیما عباسپور، فرهاد غلامی و عطا مجابی بوده است.\n\nدبیر این دوره بهروز شعیبی است و رویداد ۲۵ تا ۳۰ مهر در پردیس سینمایی ملت برپا می‌شود.",
