        category: 'جشنواره‌ها',
        summary: "فیلم کوتاه «آخرین رؤیا» ساخته تاکشی کوشیدا از ژاپن، به بخش هوش مصنوعی چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران راه یافت.",
        content: "«آخرین رؤیا» ساخته تاکشی کوشیدا از ژاپن، در فهرست فیلم‌های راه‌یافته به بخش هوش مصنوعی چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران جای گرفته است.\n\nفهرست آثار بخش بین‌الملل این دوره در پنج بخش «هوش مصنوعی»، «پویانمایی»، «مستند»، «تجربی» و «داستانی» اعلام شده و هیئت انتخاب آن را مصطفی احمدی، مجتبا اسماعیل‌زاده، سیدمحسن پورمحسنی شکیب، حمید حسینی، حسن حکمت‌روش، هادی رضایتی، دینا رضایی، روناک رنجی، مهری رحیم‌زاده، زهره زمانی، سیامک سلیمانی، فرید طهماسبی، نیما عباسپور، فرهاد غلامی و عطا مجابی تشکیل داده‌اند.\n\nجشنواره از ۲۵ تا ۳۰ مهر در پردیس سینمایی ملت برگزار می‌شود.",
