        "content": "«The Wonderful Story of Henry Sugar» به تهیه‌کنندگی وس اندرسون و استیون رالز، برنده جایزه بهترین فیلم کوتاه زنده نود و ششمین دوره اسکار شد. این فیلم اقتباسی از داستانی از رولد دال است و با سبک بصری و روایی شناخته‌شده اندرسون ساخته شده است.\n\nنامزدهای دیگر این دوره «The After»، «Invincible»، «Knight of Fortune» و «Red, White and Blue» بودند. موفقیت این فیلم نشان داد که فیلم‌سازان شناخته‌شده سینمای بلند هم می‌توانند در قالب کوتاه به جوایز مهم برسند.",
