        "content": "بر اساس آمار منبع، والت دیزنی با شش جایزه (از سیزده نامزدی) بیشترین جایزه‌ی این بخش را دارد. گوردون هولینگ‌شد هم با بیست نامزدی (و پنج جایزه) بیشترین نامزدی را ثبت کرده است.\n\nاین رکوردها به دوره‌ای مربوط‌اند که فیلم کوتاه بخشی از برنامه‌ی عادی استودیوها بود.\n\nدر بخش فیلم کوتاه زنده نیز آکادمی ۴۰ دقیقه را سقف مجاز می‌داند و پیش از اعلام نامزدها، پانزده فیلم در شورت‌لیست قرار می‌گیرند. جایزه به کسی تعلق می‌گیرد که بیش از همه مسئول ایده و اجرای خلاق فیلم بوده است.",
        "date": "1405-07-11",
