        "content": "«Sessiz-Be Deng» (Silent) ساخته ل. رزان یشیل‌باش، نخل طلای فیلم کوتاه جشنواره کن ۲۰۱۲ را گرفت. در همان سال «عشق» مایکل هانکه نخل طلای فیلم بلند را برد.\n\nاین فیلم از جمله آثار کوتاهی است که از ترکیه به بخش رقابتی کن راه یافته‌اند.\n\nنام «نخل طلا» برای جایزهٔ فیلم کوتاه کن از سال ۱۹۷۵ دوباره به کار رفته است، در حالی که فهرست برندگان این جایزه از ۱۹۵۲ و با عنوان Grand Prix آغاز می‌شود. از زمان تأسیس بخش Cinéfondation در ۱۹۹۸، نخل طلای فیلم کوتاه و جوایز Cinéfondation معمولاً توسط یک هیئت داوران مشترک داوری می‌شوند.",
