        "content": "ستاد خبری چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران، فهرست آثار بخش بین‌الملل را در پنج قالب «هوش مصنوعی»، «پویانمایی»، «مستند»، «تجربی» و «داستانی» اعلام کرد. در بخش داستانی ۲۷ فیلم پذیرفته شده است.\n\nانتخاب آثار بر عهده گروهی شامل مصطفی احمدی، مجتبا اسماعیل‌زاده، سیدمحسن پورمحسنی شکیب، حمید حسینی، حسن حکمت‌روش، هادی رضایتی و دینا رضایی بود. جشنواره ۲۵ تا ۳۰ مهر ۱۴۰۵ برگزار می‌شود.",
