        "content": "ایسفا (Iranian Short Film Academy Awards) جایزه سالانه‌ای است که انجمن فیلم کوتاه ایران برگزار می‌کند. بر اساس آیین‌نامه هفتمین جشن، آکادمی ایسفا با دست‌کم ۳۵ عضو رسمیت می‌یابد و از میان فیلم‌های دیده‌شده، ۳۰ تا ۴۰ فیلم به هیئت داوران معرفی می‌شود.\n\nجوایز شامل تندیس بهترین فیلم داستانی یا تجربی و بهترین کارگردانی در هر یک از دو بخش است و لوح تقدیر برای فیلمنامه، تصویر، تدوین و صدا داده می‌شود. در هر بخش پنج نامزد اعلام می‌شود. در سایت انجمن از برگزیدگان چهاردهمین دوره هم خبر منتشر شده است.",
