        "summary": "مسابقه بین‌المللی اوبرهاوزن امسال ۵۰ فیلم داشت که ۲۸ تای آن نخستین نمایش جهانی بودند.",
        "content": "جشنواره اوبرهاوزن اعلام کرد ۵۰ فیلم از ۳۶ کشور به مسابقه بین‌المللی راه یافته‌اند و ۲۸ تای آن‌ها نخستین نمایش جهانی را داشتند. بیش از نیمی از فیلم‌سازان این بخش سابقه مهاجرت یا پیشینه بین‌المللی داشتند.\n\nبخش کودک و نوجوان (چهل و نهمین دوره) ۳۴ فیلم از ۲۱ کشور را میان حدود ۸۰۰ ارسال نمایش داد و برای ویدئوکلیپ‌های آلمانی ۱۱ نامزد از بیش از ۲۰۰ ارسال انتخاب شد.",
        "date": "1405-07-11",
