        "content": "از ۱۹۳۲ تا ۱۹۷۰ این بخش «Short Subjects, Cartoons» و از ۱۹۷۱ تا ۱۹۷۳ «Short Subjects, Animated Films» نام داشت. نام فعلی از چهل و ششمین دوره (۱۹۷۴) رایج شد و آکادمی فیلم کوتاه را اثری تا ۴۰ دقیقه با احتساب تیتراژ تعریف می‌کند.\n\nدر پنج دهه اول، جایزه به تهیه‌کنندگان داده می‌شد؛ اکنون به فردی داده می‌شود که بیشترین نقش را در ایده و اجرای خلاق فیلم داشته است.",
