        "content": "فیلم کوتاه «شب سیاه» به کارگردانی نفیسه زهری و نویسندگی سحر میرزائیان‌فر و کامران محمدی، در دوازدهمین دوره Independent Horror Movie Awards (۲۰۲۶) جایزه بهترین فیلمبرداری (کیوان شعبانی) و بهترین موسیقی (خشایار لزومی) را گرفت.\n\nفیلم در چهار بخش دیگر هم نامزد شد: بهترین فیلم کوتاه، بهترین کارگردانی (نفیسه زهری)، بهترین صدا (خشایار لزومی) و بهترین اتمسفر. این جشنواره بیش از ۱۲ سال سابقه و بیش از ۲۰ بخش رقابتی دارد، از جمله جوایز ویژه وحشت مثل بهترین اتمسفر و بهترین ترس.",
