        "content": "به نوشته اعتماد آنلاین، در دوره‌های بیست و یکم تا سی‌ام جشنواره، سایت انجمن فیلم کوتاه ایران افتتاح، کتاب ادوار جشنواره چاپ و برگزاری جشنواره سراسری شد. بخش سینمای معناگرا در دوره بیست و یکم به جشنواره پیوست.\n\nدوره بیست و یکم ملی و نهمین بین‌المللی ۲۷ آبان تا ۲ آذر ۱۳۸۳ به دبیری محمد آفریده، دوره بیست و دوم و دهمین ۲۴ تا ۲۹ آبان ۱۳۸۴ به دبیری مجتبی اقدامی و دوره بیست و سوم و یازدهمین ۳۰ آبان تا ۵ آذر ۱۳۸۵ به دبیری ناصر باکیده در سینماهای فلسطین و قیام برگزار شد.",
        "date": "1405-07-11",
        "icon": "ri-book-open-line",
        "image": "Images/news-tehran-festival-third-decade.jpg",
        "sourceLabel": "اعتماد آنلاین",
        "sourceUrl": "https://www.etemadonline.com/%D8%A8%D8%AE%D8%B4-%D9%81%D8%B1%D9%87%D9%86%DA%AF-%D9%87%D9%86%D8%B1-16/442389-%D8%AA%D8%AD%D9%88%D9%84%D8%A7%D8%AA-%D8%AC%D8%B4%D9%86%D9%88%D8%A7%D8%B1%D9%87-%D9%81%DB%8C%D9%84%D9%85-%DA%A9%D9%88%D8%AA%D8%A7%D9%87-%D8%AA%D9%87%D8%B1"
