        "content": "جشنواره اتاوا که ۱۹۷۵ توسط مؤسسه فیلم کانادا بنیان‌گذاری شد و اولین بار در اوت ۱۹۷۶ برگزار شد، بزرگ‌ترین و قدیمی‌ترین جشنواره انیمیشن آمریکای شمالی است. جایزه بزرگ آن را «پرسپولیس» (۲۰۰۷) و «ماری و مکس» (۲۰۰۹) هم گرفته‌اند.\n\nکنفرانس انیمیشن (TAC) هم همزمان با جشنواره برگزار می‌شود و اتاوا را به مرکز صنعتی انیمیشن تبدیل می‌کند.",
