        "content": "انیمیشن کوتاه «ناگفته نماند» ساخته محبوبه کلایی و علی فتوحی جایزه «نه به خشونت» جشنواره Ann Arbor آمریکا را گرفت. این جایزه به فیلمی داده می‌شود که در فرهنگی که از تصاویر خشن برای سرگرمی و اطلاع‌رسانی استفاده می‌کند، به اصل عدم خشونت پایبند می‌ماند.\n\nفیلم، که تولید مرکز گسترش سینمای مستند، تجربی و پویانمایی است، پیش‌تر جایزه بهترین فیلم بخش بین‌الملل بیست و دومین جشنواره اژدهای طلایی چین را هم گرفته بود. خبر ۲۳ اردیبهشت ۱۴۰۵ منتشر شد.",
