        "content": "آسپن شورت‌فست ۲۰۲۶ از ۷ تا ۱۱ آوریل در آسپن (کلرادو) برگزار شد. در ۱۰ بلوک برنامه شامل فیلم داستانی، کمدی، مستند و انیمیشن و ۳۷ نمایش اول در ایالت کلرادو بود. شورت‌فست در انیمیشن، کمدی، مستند، درام و فیلم‌های زیر ۱۰ دقیقه واجد شرایط اسکار است.\n\n«Jane Austen's Period Drama» با جایزه هیئت داوران کمدی ۲۰۲۵ واجد شرایط شد و نامزد اسکار فیلم کوتاه زنده شد؛ «Retirement Plan» هم نامزد اسکار انیمیشن کوتاه شد. استف کری و رنه زلویگر هم با فیلم‌هایی در برنامه ۲۰۲۶ بودند.",
