        "content": "فراخوان ملی و بین‌المللی نوزدهمین جشنواره بین‌المللی فیلم کوتاه دانشجویی نهال منتشر شد و دبیرخانه از ۱۷ اردیبهشت ۱۴۰۲ آماده دریافت آثار بود. بخش‌ها: فیلم کوتاه (داستانی، مستند، تجربی و انیمیشن)، فیلمنامه و عکس و پوستر فیلم.\n\nدر بخش جنبی «عکس و پوستر» آثار به دو شکل رقابتی و غیررقابتی پذیرفته می‌شوند و مجموعه عکس می‌تواند پشت صحنه، گریم و تمرین بازیگران را شامل شود. اگر اثر برگزیده را چند نفر نوشته باشند، فقط یک جایزه می‌گیرد.",
