        "title": "اسکار انیمیشن کوتاه ۱۹۸۳ تا ۱۹۸۷: «Sundae in New York»، «Charade»، «Anna & Bella» و «A Greek Tragedy»",
        "category": "سینمای جهان",
        "summary": "چهار فیلم کوتاه در سال‌های متوالی اسکار انیمیشن را بردند.",
        "content": "برندگان: «Sundae in New York» (جیمی پیکر، فیلم ۱۹۸۳)، «Charade» (جان مینیس، ۱۹۸۴)، «Anna & Bella» (سیلیا فن دایک، ۱۹۸۵) و «A Greek Tragedy» (لیندا فن تولدن و ویلم تایسن، ۱۹۸۶).\n\n«Anna & Bella» و «A Greek Tragedy» هر دو از هلند بودند.\n\nو در دورهٔ بعد، ۵۷مین اسکار، «Charade» (جان مینیس) جایزه را گرفت. پیش از آن، در دورهٔ ۵۶ اسکار، «Sundae in New York» (جیمی پیکر) برنده شده بود، و در دورهٔ بعد، ۵۸مین اسکار، «Anna & Bella» (سیلیا فن دایک) جایزه را گرفت. پیش از آن، در دورهٔ ۵۷ اسکار، «Charade» (جان مینیس) برنده شده بود، و در دورهٔ بعد، ۵۹مین اسکار، «A Greek Tragedy» (ویلم تایسن و لیندا فن تولدن) جایزه را گرفت. پیش از آن، در دورهٔ ۵۸ اسکار، «Anna & Bella» (سیلیا فن دایک) برنده شده بود، و در دورهٔ بعد، ۶۰مین اسکار، «The Man Who Planted Trees» (فردریک بک) جایزه را گرفت.\n\n«Sundae in New York» (جیمی پیکر) در دورهٔ ۵۶، «Charade» (جان مینیس) در دورهٔ ۵۷، «Anna & Bella» (سیلیا فن دایک) در دورهٔ ۵۸ و «A Greek Tragedy» (ویلم تایسن و لیندا فن تولدن) در دورهٔ ۵۹ برندهٔ اسکار انیمیشن کوتاه شدند.\n\n## درباره جایزه اسکار بهترین انیمیشن کوتاه\n\nجایزه اسکار برای انیمیشن کوتاه نخستین بار ۱۸ نوامبر ۱۹۳۲ و برای فیلم‌های فصل ۱۹۳۱/۱۹۳۲ اهدا شد و نخستین برنده آن «Flowers and Trees» بود. نام این بخش در سال‌های ۱۹۳۲ تا ۱۹۷۰ «فیلم‌های کوتاه، کارتون» و در ۱۹۷۱ تا ۱۹۷۳ «فیلم‌های کوتاه، انیمیشن» بود و عنوان فعلی از دورهٔ چهل‌وششم، در ۱۹۷۴، رواج یافت.\n\nآکادمی فیلم کوتاه را اثری حداکثر ۴۰ دقیقه، با احتساب تیتراژ، تعریف می‌کند. جایزه به کسی می‌رسد که بیش از همه مسئول ایده و اجرای خلاق فیلم بوده است و اگر بیش از یک نفر در تصمیم‌های خلاقانه نقش مهمی داشته باشند، ممکن است مجسمهٔ دوم هم اهدا شود.",
