        "category": "سینمای جهان",
        "summary": "فیلم «Tin Toy» ساخته جان لستر و ویلیام ریوز برنده اسکار شد.",
        "content": "«Tin Toy» ساخته جان لستر (John Lasseter) و ویلیام ریوز (William Reeves) در شصت و یکمین اسکار برنده بهترین انیمیشن کوتاه شد. پیش‌تر در ۱۹۸۷ هم این دو برای فیلم دیگری نامزد شده بودند.\n\nدر فهرست جوایز پیکسار، «Tin Toy» نخستین اسکار انیمیشن کوتاه این استودیو است.\n\nپیش از آن، در دورهٔ ۶۰ اسکار، «The Man Who Planted Trees» (فردریک بک) برنده شده بود، و در دورهٔ بعد، ۶۲مین اسکار، «Balance» (ولفگانگ و کریستف لائنشتاین) جایزه را گرفت.\n\n«Tin Toy» ساختهٔ جان لستر و بیل ریوز برنده اسکار انیمیشن کوتاه دورهٔ ۶۱ شد و در فهرست جوایز پیکسار نخستین اسکار انیمیشن کوتاه این استودیو ثبت شده است. در این فهرست، پیکسار روی‌هم‌رفته ۵ برد در این بخش دارد.\n\n## درباره جایزه اسکار بهترین انیمیشن کوتاه\n\nجایزه اسکار برای انیمیشن کوتاه نخستین بار ۱۸ نوامبر ۱۹۳۲ و برای فیلم‌های فصل ۱۹۳۱/۱۹۳۲ اهدا شد و نخستین برنده آن «Flowers and Trees» بود. نام این بخش در سال‌های ۱۹۳۲ تا ۱۹۷۰ «فیلم‌های کوتاه، کارتون» و در ۱۹۷۱ تا ۱۹۷۳ «فیلم‌های کوتاه، انیمیشن» بود و عنوان فعلی از دورهٔ چهل‌وششم، در ۱۹۷۴، رواج یافت.\n\nآکادمی فیلم کوتاه را اثری حداکثر ۴۰ دقیقه، با احتساب تیتراژ، تعریف می‌کند. جایزه به کسی می‌رسد که بیش از همه مسئول ایده و اجرای خلاق فیلم بوده است و اگر بیش از یک نفر در تصمیم‌های خلاقانه نقش مهمی داشته باشند، ممکن است مجسمهٔ دوم هم اهدا شود.",
