        "category": "سینمای جهان",
        "summary": "نیک پارک در ۱۹۹۰ و ۱۹۹۳ و ۱۹۹۵ در فهرست برندگان اسکار انیمیشن کوتاه است.",
        "content": "فهرست برندگان نشان می‌دهد نیک پارک (Nick Park) برای «Creature Comforts» (فیلم ۱۹۹۰)، «The Wrong Trousers» (۱۹۹۳) و «A Close Shave» (۱۹۹۵) اسکار گرفته است.\n\n«The Wrong Trousers» و «A Close Shave» از ماجراهای والاس و گرومیت هستند.\n\nنیک پارک با سه اسکار انیمیشن کوتاه در فهرست برندگان دیده می‌شود: «Creature Comforts» (فیلم سال ۱۹۹۰، دورهٔ ۶۳)، «The Wrong Trousers» (۱۹۹۳، دورهٔ ۶۶) و «A Close Shave» (۱۹۹۵، دورهٔ ۶۸). میان دو اسکار اول او، «Manipulation» (دنیل گریوز) و «Mona Lisa Descending a Staircase» (جوآن گرتز) برنده شدند و پس از او «Bob's Birthday» (دیوید فاین و آلیسون اسنودن) جایزه را گرفت.\n\n## درباره جایزه اسکار بهترین انیمیشن کوتاه\n\nجایزه اسکار برای انیمیشن کوتاه نخستین بار ۱۸ نوامبر ۱۹۳۲ و برای فیلم‌های فصل ۱۹۳۱/۱۹۳۲ اهدا شد و نخستین برنده آن «Flowers and Trees» بود. نام این بخش در سال‌های ۱۹۳۲ تا ۱۹۷۰ «فیلم‌های کوتاه، کارتون» و در ۱۹۷۱ تا ۱۹۷۳ «فیلم‌های کوتاه، انیمیشن» بود و عنوان فعلی از دورهٔ چهل‌وششم، در ۱۹۷۴، رواج یافت.\n\nآکادمی فیلم کوتاه را اثری حداکثر ۴۰ دقیقه، با احتساب تیتراژ، تعریف می‌کند. جایزه به کسی می‌رسد که بیش از همه مسئول ایده و اجرای خلاق فیلم بوده است و اگر بیش از یک نفر در تصمیم‌های خلاقانه نقش مهمی داشته باشند، ممکن است مجسمهٔ دوم هم اهدا شود.",
