        "category": "سینمای ایران",
        "summary": "فهرست ۶۳ فیلم داستانی بخش ملی با انتخاب اسما ابراهیم‌زادگان، الهام اسدی، محسن اصدق‌پور، رضا فهیمی، وحید موسائیان، الهام معروفی و وحید نامی اعلام شد.",
        "content": "به گزارش خبرگزاری دانشجو، ۶۳ فیلم کوتاه داستانی به بخش ملی چهل‌وسومین جشنواره بین‌المللی فیلم کوتاه تهران راه یافتند. هیئت انتخاب: اسما ابراهیم‌زادگان، الهام اسدی، محسن اصدق‌پور، رضا فهیمی، وحید موسائیان، الهام معروفی و وحید نامی.\n\nاز فیلم‌ها: «آدم» (فرهاد شنتیایی)، «وراپام» (نازنین چیت‌ساز)، «ترمینال» (علیرضا خانی)، «همو_فیلیا» (کیارش صالحی)، «منجمد» (احمد سلگی)، «ژاپنی» (پناه الوانی)، «شب‌زده» (نیلوفر فولادی) و «کاتر» (حسین حیاتی). جشنواره ۲۵ تا ۳۰ مهر ۱۴۰۵ به دبیری بهروز شعیبی برگزار می‌شود.",
