        "content": "فیلم‌های کائوشیونگ باید ۲۵ دقیقه یا کمتر (با تیتراژ) باشند. داستانی، مستند، تجربی و انیمیشن پذیرفته می‌شود. بخش تایوان برای کارگردانان تایوانی یا فیلم‌های ساخته‌شده در تایوان است و جایزه دانشجویی تایوان برای فیلمی که سازنده‌اش دانشجو بوده.\n\nارسال ۱ آوریل تا ۱۰ ژوئن ۲۰۲۶ بود. جایزه هیئت کودکان برای فیلم‌های مناسب کودکان ۹ تا ۱۲ ساله است.",
