        "content": "در هجدهمین مسابقه NRW اوبرهاوزن، «Garden of Edie» ساخته میری کلیشات جایزه ۱۰۰۰ یورویی را گرفت. جایزه تشویقی ۵۰۰ یورویی به «Ku Yendza (Trajectories)» از سیمون ریتمایر رسید و «HOPE ROAD» از سوزان ماریا همپل هم تقدیر ویژه و جایزه ۷۵۰ یورویی هیئت تماشاگران WDR Westart را دریافت کرد.\n\nاین جایزه در اختتامیهٔ ۳ مه ۲۰۲۶ اعلام شد.\n\nهفتاد‌ودومین جشنواره بین‌المللی فیلم کوتاه اوبرهاوزن از ۲۸ آوریل تا ۳ مه ۲۰۲۶ برگزار شد. مدیر هنری جشنواره مادلین برنشتورف است. در مجموع ۱۲۱ فیلم و موزیک‌ویدیو از ۴۸ کشور نمایش داده شد و بیش از ۷٬۶۰۰ فیلم از ۱۲۴ کشور برای جشنواره ارسال شده بود؛ رقمی که رکورد این جشنواره است. در پایان، ۲۱ جایزه در چهار مسابقه اهدا شد و مجموع مبلغ جوایز نزدیک ۴۵ هزار یورو بود.",
