        "category": "جشنواره‌ها",
        "summary": "چهار جایزه ۱۰۰۰ یورویی در چهل‌ونهمین مسابقه فیلم کودک و نوجوان اهدا شد.",
        "content": "در چهل‌ونهمین مسابقه بین‌المللی فیلم کودک و نوجوان اوبرهاوزن، جایزه هیئت کودکان به «Under The Wave off Little Dragon» (لو جیان، بریتانیا) رسید و جایزه evo هیئت کودکان به «My Shadow and I» (یالی هربت، اسرائیل).\n\nجایزه هیئت نوجوانان به «A Dog in a Trap» (شینینگ لائو، آمریکا) و جایزه SURPRISE به «Mappillai» (The Groom) از Padakathai Illaka Collective رسید؛ هر جایزه ۱۰۰۰ یورو.\n\nاین جایزه در اختتامیهٔ ۳ مه ۲۰۲۶ اعلام شد.\n\nهفتاد‌ودومین جشنواره بین‌المللی فیلم کوتاه اوبرهاوزن از ۲۸ آوریل تا ۳ مه ۲۰۲۶ برگزار شد. مدیر هنری جشنواره مادلین برنشتورف است. در مجموع ۱۲۱ فیلم و موزیک‌ویدیو از ۴۸ کشور نمایش داده شد و بیش از ۷٬۶۰۰ فیلم از ۱۲۴ کشور برای جشنواره ارسال شده بود؛ رقمی که رکورد این جشنواره است. در پایان، ۲۱ جایزه در چهار مسابقه اهدا شد و مجموع مبلغ جوایز نزدیک ۴۵ هزار یورو بود.",
