        "content": "انیمیشن «Paper Trail» ساخته دان هرتزفلت (آمریکا) جایزه ویژه هیئت داوران برای دیدگاه خلاق در بخش فیلم کوتاه ساندنس ۲۰۲۶ را برد. داوران از ظرافت ساخت فیلم و اینکه چگونه یک ایده ساده نگاه بیننده به جهان را گسترش می‌دهد گفتند.\n\n«Paper Trail» با توصیف «یک زندگی که از دریچهٔ کاغذ دیده می‌شود» معرفی شده و در ساندنس نمایش جهانی اول داشت.\n\nبرنامه فیلم کوتاه ساندنس ۲۰۲۶ شامل ۵۴ فیلم بود که از میان ۱۱٬۴۸۰ فیلم ارسالی انتخاب شدند. جشنواره از ۲۲ ژانویه تا ۱ فوریه در پارک سیتی و سالت‌لیک‌سیتی (ایالت یوتا) برگزار شد و جوایز فیلم کوتاه را هیئت داوران سه‌نفره‌ای شامل ای.وی. راکول، لیو کانستیبل-مکسول و مارتین استار تعیین کردند. بیشتر فیلم‌های برنده از ۲۹ ژانویه تا ۱ فوریه در سراسر آمریکا به‌صورت آنلاین هم قابل دیدن بودند.",
