        "content": "دیگر فیلم‌های برنامه کلرمون-فران ۲۰۲۶: «Air Horse One» (لازه لیندر، سوئیس)، «Vultures» (دیان ویس، فرانسه/آفریقای جنوبی)، «Death of a Fantastic Machine» (اکسل دانیلسون و ماکسیمیلین فن آرتریک، سوئد) و «Their Eyes» (نیکلا گورنولت، فرانسه).\n\n«Air Horse One» از لازه لیندر (سوئیس)، «Vultures» از دیان ویس (فرانسه/آفریقای جنوبی)، «Death of a Fantastic Machine» از اکسل دانیلسون و ماکسیمیلین فن آرتریک (سوئد) و «Their Eyes» از نیکلا گورنولت (فرانسه) از جمله فیلم‌های برنامه بودند. جشنواره از ۳۰ ژانویه تا ۷ فوریه ۲۰۲۶ برگزار شد.",
