        "category": "سینمای جهان",
        "summary": "اثر توبیاس اکرلین از فیلم‌آکادمی بادن‌وورتمبرگ.",
        "content": "در جوایز انی ۲۰۲۶، «A Sparrow's Song» به کارگردانی دانشجویی توبیاس اکرلین از Filmakademie Baden-Württemberg برنده بهترین فیلم دانشجویی شد.\n\nنامزدهای بهترین فیلم دانشجویی انی ۲۰۲۶ عبارت بودند از «A Sparrow's Song»، «Acrobats» (Gobelins)، «Jour de vent» (École des Nouvelles Images)، «The Undying Pain of Existence» (که آن هم از Filmakademie Baden-Württemberg بود) و «TRASH» (ESMA). مراسم ۲۱ فوریه ۲۰۲۶ در تالار رویس دانشگاه کالیفرنیا، لس‌آنجلس برگزار شد.",
