            content: 'فیلم کوتاه «ماندالا» به نویسندگی و کارگردانی بهنام خسروی موفق شد جایزه بهترین فیلم را از جشنواره بین‌المللی Accolade Global Film Competition دریافت کند؛ نخستین گام بزرگ این فیلم کوتاه ایرانی در مسیری که بعدها به یکی از پرافتخارترین حضورهای بین‌المللی یک اثر کوتاه مستقل ایرانی در چند سال اخیر تبدیل شد.\n\nجشنواره Accolade که هر ساله آثار مستقل از سراسر جهان را در بخش‌های متعدد از جمله بهترین فیلم، کارگردانی، فیلم‌نامه، تدوین و بازیگری داوری می‌کند، «ماندالا» را به دلیل کیفیت روایت، ساختار بصری منسجم و اجرای حرفه‌ای در میان آثار برگزیده بخش بهترین فیلم خود قرار داد. عبور از این مرحله داوری، معمولاً به‌معنای رقابت با صدها اثر ارسالی از کشورهای مختلف است؛ رقابتی که در آن «ماندالا» توانست با تکیه بر روایت فشرده و لایه‌های نمادین خود، توجه هیئت داوران را جلب کند.\n\nبه گفته برخی از منتقدانی که «ماندالا» را در این دوره از جشنواره دیده‌اند، آنچه این فیلم را از میان رقبای خود متمایز کرده، ترکیب هم‌زمان یک فیلم‌نامه فشرده با اجرایی کم‌هزینه اما دقیق بوده است؛ رویکردی که نشان می‌دهد محدودیت بودجه در فیلم کوتاه مستقل، لزوماً به معنای افت کیفیت روایی نیست. بهنام خسروی که در «ماندالا» هم‌زمان نویسندگی، کارگردانی و تدوین را بر عهده داشت، این هماهنگی میان بخش‌های مختلف تولید را یکی از دلایل اصلی موفقیت فیلم می‌داند.\n\nاین جایزه یکی از نخستین افتخارات بین‌المللی «ماندالا» بود و مسیر حضور این فیلم کوتاه در جشنواره‌های بعدی از جمله دهمین جشنواره بین‌المللی فیلم TINFF کانادا، جشنواره بین‌المللی فیلم پونه در هندوستان و در نهایت جشنواره Stay Gold Film Festival را هموار کرد. جشنواره Accolade در ادامه همکاری خود با «ماندالا»، بار دیگر و در دوره‌ای دیگر، جایزه بهترین بازیگر نقش اول مرد را نیز به بهنام خسروی برای اجرای نقش اصلی همین فیلم اهدا کرد؛ رویدادی که «ماندالا» را به یکی از معدود آثار کوتاهی تبدیل کرد که از یک جشنواره واحد، دو جایزه جداگانه در دو دوره متفاوت دریافت کرده‌اند.\n\nتیم سازنده «ماندالا» این جایزه را نقطه آغاز مسیری دانستند که در ادامه آن، این فیلم کوتاه ایرانی توانست حضوری مستمر و رو به رشد در جشنواره‌های بین‌المللی داشته باشد. تیم مستر شورت‌فیلم مسیر جوایز و حضور بین‌المللی این فیلم را در همین بخش وبلاگ دنبال خواهد کرد.',
