            content: 'فیلم کوتاه «ماندالا» به کارگردانی بهنام خسروی به عنوان یکی از آثار حاضر در جشنواره بین‌المللی فیلم پونه هندوستان معرفی شد؛ حضوری که دامنه جغرافیایی استقبال از این فیلم کوتاه ایرانی را به قاره آسیا نیز گسترش داد.\n\nجشنواره بین‌المللی فیلم پونه یکی از رویدادهای شناخته‌شده سینمایی در هندوستان است که هر ساله آثار داستانی، مستند و کوتاه را از فیلمسازان مستقل سراسر جهان گرد هم می‌آورد. راه‌یابی «ماندالا» به بخش رسمی این جشنواره، در ادامه سلسله موفقیت‌های بین‌المللی این فیلم و پس از حضور در جشنواره Accolade و نامزدی بهترین کارگردانی در TINFF کانادا رقم خورد.\n\nاین حضور، ادامه مسیر موفق «ماندالا» در جشنواره‌های بین‌المللی بود و بار دیگر نشان داد که این فیلم کوتاه ایرانی، با وجود روایتی کاملاً بومی و ریشه‌دار در فضای فرهنگی ایران، توانسته مضمون هویت و فراموشی خود را به زبانی جهان‌شمول ترجمه کند و توجه داوران و مخاطبان در فرهنگ‌ها و جغرافیاهای متفاوت را جلب کند؛ ویژگی‌ای که به باور بسیاری از فیلمسازان مستقل، دستیابی به آن یکی از دشوارترین بخش‌های ساخت یک فیلم کوتاه با مخاطب بین‌المللی است.\n\nحضور در پونه هند، سومین ایستگاه بین‌المللی «ماندالا» به شمار می‌رفت و بر تداوم استقبال جشنواره‌های آسیایی از این اثر تاکید داشت. این رویداد همچنین فرصتی برای معرفی بیشتر سینمای کوتاه مستقل ایران به مخاطبان و اهالی رسانه در شبه‌قاره هند فراهم کرد؛ منطقه‌ای که در سال‌های اخیر به یکی از بازارهای رو به رشد برای آثار مستقل سینمایی تبدیل شده است.\n\nبهنام خسروی، نویسنده و کارگردان «ماندالا»، حضور در جشنواره پونه را فرصتی برای گفت‌وگوی فرهنگی میان سینمای ایران و هند دانست و از استقبال داوران و مخاطبان این جشنواره از فیلم کوتاه خود ابراز خرسندی کرد. تیم مستر شورت‌فیلم مسیر حضور بین‌المللی «ماندالا» را همچنان در همین بخش وبلاگ دنبال خواهد کرد.',
