            content: 'فیلم کوتاه «ماندالا» به نویسندگی و کارگردانی بهنام خسروی، روایتی است درباره هویت و فراموشی و اینکه انسان چگونه با بخش‌هایی از گذشته خود روبه‌رو می‌شود که ترجیح می‌دهد آن‌ها را به یاد نیاورد. این مضمون، اگرچه در نگاه نخست ساده به نظر می‌رسد، اما در دست خسروی به روایتی چندلایه تبدیل شده که هر بار تماشا، جزئیات تازه‌ای از خود آشکار می‌کند.\n\nخسروی که پیش‌تر تجربه رمان‌نویسی نیز داشته، در «ماندالا» از همان نگاه لایه‌لایه و نمادین حاضر در آثار داستانی‌اش در ساختار روایت فیلم بهره برده است؛ نامی که خود به شکلی نمادین به مفهوم چرخه، کمال و بازگشت در فرهنگ‌های مختلف اشاره دارد. انتخاب این عنوان برای فیلمی که محور آن گذشته و حافظه است، به گفته برخی از منتقدان، به‌خودی‌خود بخشی از پیام فیلم را در خود حمل می‌کند؛ ایده‌ای که انسان همواره در چرخه‌ای از یادآوری و فراموشی گرفتار است.\n\nاز نظر ساختاری، «ماندالا» با اتکا بر ریتمی آرام و فضاسازی بصری دقیق، از دیالوگ‌محوری فاصله می‌گیرد و بخش قابل توجهی از روایت خود را از طریق تصویر، سکوت و بازی درونی بازیگران منتقل می‌کند؛ رویکردی که در سینمای کوتاه مستقل کمتر با موفقیت اجرا می‌شود، اما در این فیلم توانسته مخاطب را بدون نیاز به توضیح مستقیم، با دنیای درونی شخصیت اصلی همراه کند.\n\nهمین رویکرد روایی و بصری بود که باعث شد فیلم در جشنواره‌های متعدد بین‌المللی از جمله Accolade Global Film Competition، TINFF کانادا، جشنواره پونه هندوستان و Stay Gold Film Festival مورد توجه قرار گیرد؛ استقبالی که نشان می‌دهد مضمون هویت و فراموشی، فارغ از زبان و فرهنگ، برای مخاطبان در جغرافیاهای مختلف قابل درک و همذات‌پنداری بوده است.\n\nبدون آنکه داستان فیلم لو برود، می‌توان گفت «ماندالا» مخاطب را به سفری درونی دعوت می‌کند که در آن مرز میان خاطره و واقعیت به آرامی محو می‌شود؛ سفری که پایان آن، بیش از آنکه پاسخی قطعی ارائه دهد، پرسشی تازه در ذهن تماشاگر باقی می‌گذارد. همین ویژگی است که به باور بسیاری از مفسران سینمای کوتاه، «ماندالا» را از یک روایت ساده به تجربه‌ای تاملی درباره حافظه و هویت انسانی تبدیل کرده است.',
